Link: https://lore.kernel.org/r/20220316192010.19001-2-rdunlap@infradead.org
Signed-off-by: Jens Axboe <axboe@kernel.dk>

Here is the root cause:
The use of anonymous module initialization and exit functions can lead to confusion and ambiguity in system logs, such as System.map and initcall_debug logs, making it difficult to trace issues related to module loading and unloading. This can result in challenges when diagnosing crashes, oops, or bugs, as multiple functions may appear with the same name, hindering effective debugging.

Here is the patch:

-static int __init init(void)
+static int __init virtio_blk_init(void)
 {
 	int error;

 	virtblk_wq = alloc_workqueue("virtio-blk", 0, 0);
 	if (!virtblk_wq)
 		return -ENOMEM;

 	major = register_blkdev(0, "virtblk");
 	if (major < 0) {
 		error = major;
 		goto out_destroy_workqueue;
 	}

 	error = register_virtio_driver(&virtio_blk);
 	if (error)
 		goto out_unregister_blkdev;
 	return 0;

 out_unregister_blkdev:
 	unregister_blkdev(major, "virtblk");
 out_destroy_workqueue:
 	destroy_workqueue(virtblk_wq);
 	return error;
 }

-static void __exit fini(void)
+static void __exit virtio_blk_fini(void)
 {
 	unregister_virtio_driver(&virtio_blk);
 	unregister_blkdev(major, "virtblk");
 	destroy_workqueue(virtblk_wq);
 }
-module_init(init);
-module_exit(fini);
+module_init(virtio_blk_init);
+module_exit(virtio_blk_fini);

 MODULE_DEVICE_TABLE(virtio, id_table);


